"""Local mode: the same batches as omrun.py, generated by a ComfyUI on this computer (ComfyUI Desktop, port 8188).

No Colab, no GPU to rent or release. The job runner (remote/remote_job.py) and the graphs (remote/graphs.py)
are the very same code the Colab mode uses; only the ComfyUI they talk to is local.

  python omlocal.py check [--features t2i,edit,video]   ComfyUI up? VRAM tier? models and nodes present?
  python omlocal.py setup [--features t2i,edit,video]   download missing models, clone the node packs the tier needs
  python omlocal.py run <manifest.json> [--confirmed] [--force]

The VRAM tier is read from ComfyUI: 20 GB or more = high (bf16/fp16), 10-19 GB = low (int8 / GGUF, e.g. RTX 3060 12 GB).
Override with --tier. ComfyUI Desktop keeps models in ~/ComfyUI-Shared/models by default.
"""
import argparse
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
SKILL = HERE.parent
sys.path.insert(0, str(SKILL / "remote"))
sys.path.insert(0, str(HERE))
import graphs as G                                                         # noqa: E402
import models as M                                                         # noqa: E402
from omrun import load_manifest, skip_finished, spec_summary, DEFAULT_RES  # noqa: E402

ENV = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
ALL_FEATURES = ("t2i", "edit", "video")


def get(url, timeout=5):
    with urllib.request.urlopen(url, timeout=timeout) as r:
        return json.loads(r.read() or b"{}")


# ---------------------------------------------------------------- what this ComfyUI looks like
class Comfy:
    """Where this ComfyUI keeps things. ComfyUI Desktop starts main.py with --base-directory (and often
    --input-directory); a portable build gives only a relative main.py, so --comfy-dir fills the gap."""

    def __init__(self, url, models_dir=None, comfy_dir=None):
        self.url = url.rstrip("/")
        try:
            self.stats = get(self.url + "/system_stats")
        except Exception:
            self.stats = None
            return
        argv = self.stats.get("system", {}).get("argv", [])
        flag = lambda k: argv[argv.index(k) + 1] if k in argv and argv.index(k) + 1 < len(argv) else None
        main_py = Path(argv[0]) if argv else Path("main.py")
        base = comfy_dir or flag("--base-directory") or (main_py.parent if main_py.is_absolute() else None)
        self.base = Path(base) if base else None
        inp = flag("--input-directory") or (self.base / "input" if self.base else None)
        self.input = Path(inp) if inp else None
        shared = Path.home() / "ComfyUI-Shared" / "models"
        self.models = Path(models_dir) if models_dir else (
            shared if shared.is_dir() or not self.base else self.base / "models")
        self.custom_nodes = self.base / "custom_nodes" if self.base else None
        self._lists = {}

    @property
    def up(self):
        return self.stats is not None

    def listing(self, folder):
        """What ComfyUI itself sees in a model folder (all configured paths, subfolders included)."""
        if folder not in self._lists:
            try:
                self._lists[folder] = {Path(n.replace("\\", "/")).name for n in get(f"{self.url}/models/{folder}", 30)}
            except Exception:
                self._lists[folder] = set()  # a folder only a node pack registers, or not registered yet
        return self._lists[folder]

    def has_model(self, folder, name):
        name = Path(name).name
        if name.endswith(".gguf"):  # ComfyUI-GGUF lists .gguf files under its own folder name
            folder_listed = name in self.listing("unet_gguf") or name in self.listing("clip_gguf")
            if folder_listed:
                return True
        return name in self.listing(folder) or (self.models / folder / name).is_file() or bool(
            self.base and (self.base / "models" / folder / name).is_file())

    def target(self, folder):
        return self.models / folder

    def python(self):
        """ComfyUI Desktop's own venv (or the portable embedded one): node pack requirements go there."""
        if self.base:
            for p in (self.base / ".venv" / "Scripts" / "python.exe", self.base / ".venv" / "bin" / "python",
                      self.base.parent / "python_embeded" / "python.exe"):
                if p.is_file():
                    return str(p)
        return sys.executable


def vram_gb(c):
    dev = (c.stats.get("devices") or [{}])[0]
    return dev.get("vram_total", 0) / 2**30, dev.get("name", "?")


def pick_tier(c, forced=None):
    if forced:
        return forced
    vram, _ = vram_gb(c)
    return M.tier_for(vram)


def needed(features, tier):
    return M.files_for(features, tier)


def missing_models(c, features, tier):
    return [f for f in needed(features, tier) if not c.has_model(f[2], f[1])]


def missing_nodes(c, features, tier):
    """Node classes the graphs for these features will submit that this ComfyUI does not know."""
    try:
        known = set(get(c.url + "/object_info", timeout=60))
    except Exception:
        return ["（讀不到 /object_info）"]
    want = set()
    models = {f: M.FEATURES[f][tier] for f in features}
    if "t2i" in features:
        want |= {n["class_type"] for n in G.t2i({"id": "x", "prompt": "x", "seed": 1}, models["t2i"])[0].values()}
    if "edit" in features:
        want |= {n["class_type"] for n in G.edit({"id": "x", "prompt": "x", "seed": 1}, models["edit"], ["x.png"])[0].values()}
    if "video" in features:
        want |= {n["class_type"] for n in G.video({"id": "x", "prompt": "x", "seed": 1}, models["video"], "x.png")[0].values()}
    return sorted(want - known)


def parse_features(text):
    fs = [f.strip() for f in (text or ",".join(ALL_FEATURES)).split(",") if f.strip()]
    bad = [f for f in fs if f not in ALL_FEATURES]
    if bad:
        sys.exit(f"--features 只能是 {ALL_FEATURES}：{bad}")
    return fs


# ---------------------------------------------------------------- check / setup
def check(args, features, quiet=False):
    c = Comfy(args.comfy, args.models_dir, args.comfy_dir)
    if not c.up:
        print(f"❌ {args.comfy} 沒有回應：先打開 ComfyUI Desktop（要先安裝好：https://comfy.org/download）")
        return c, None, False
    vram, gpu = vram_gb(c)
    try:
        tier = pick_tier(c, args.tier)
    except RuntimeError as e:
        print(f"❌ {gpu}：{e}，建議改用 Colab（omrun.py）")
        return c, None, False
    print(f"✅ ComfyUI {c.stats.get('system', {}).get('comfyui_version', '?')}　{gpu}　VRAM {vram:.0f} GB　→ 等級 {tier}")
    print(f"   模型資料夾：{c.models}")
    ok = True
    if not c.input:
        ok = False
        print("❌ 找不到 ComfyUI 的資料夾（input／custom_nodes 在哪）：加上 --comfy-dir <ComfyUI 資料夾>")
    miss = missing_models(c, features, tier)
    if miss:
        ok = False
        print(f"❌ 少 {len(miss)} 個模型（約 {sum(f[3] for f in miss):.0f} GB）：" + "、".join(Path(f[1]).name for f in miss))
    nodes = missing_nodes(c, features, tier)
    if nodes:
        ok = False
        print("❌ ComfyUI 不認得這些節點：" + "、".join(nodes))
        print("   （節點組沒裝、裝了還沒重開 ComfyUI，或 ComfyUI Desktop 太舊：先更新到最新版）")
    print("✅ 可以開始生成" if ok else "→ 執行 `python omlocal.py setup`，照它說的做完、重開 ComfyUI Desktop，再 check 一次")
    return c, tier, ok


def fetch(repo, name, dst):
    """Plain HTTP download with resume (no extra packages)."""
    url = f"https://huggingface.co/{repo}/resolve/main/{name}"
    part = dst.with_suffix(dst.suffix + ".part")
    dst.parent.mkdir(parents=True, exist_ok=True)
    have = part.stat().st_size if part.exists() else 0
    req = urllib.request.Request(url, headers={"Range": f"bytes={have}-"} if have else {})
    tok = os.environ.get("HF_TOKEN")
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")
    with urllib.request.urlopen(req, timeout=60) as r, open(part, "ab" if have else "wb") as f:
        total = have + int(r.headers.get("Content-Length") or 0)
        t0, last = time.time(), 0
        while True:
            chunk = r.read(8 << 20)
            if not chunk:
                break
            f.write(chunk)
            have += len(chunk)
            if time.time() - last > 15:
                last = time.time()
                print(f"   {dst.name}  {have / 2**30:.1f}/{total / 2**30:.1f} GiB", flush=True)
    part.replace(dst)


def git_clone(url, dest, commit):
    dest = Path(dest)
    if not dest.is_dir():
        subprocess.run(["git", "clone", "--filter=blob:none", url, str(dest)], check=True)
    subprocess.run(["git", "-C", str(dest), "checkout", "-q", commit], check=True)


def setup(args):
    features = parse_features(args.features)
    c = Comfy(args.comfy, args.models_dir, args.comfy_dir)
    if not c.up:
        sys.exit(f"❌ {args.comfy} 沒有回應：先打開 ComfyUI Desktop")
    tier = pick_tier(c, args.tier)
    print(f"等級 {tier}，功能 {', '.join(features)}")
    new_nodes = []
    if M.NODES[tier] and missing_nodes(c, features, tier):
        if not c.custom_nodes:
            sys.exit("❌ 找不到 ComfyUI 的資料夾：加上 --comfy-dir <ComfyUI 資料夾>（有 custom_nodes 的那一層）")
        print(f"① 節點組 → {c.custom_nodes}")
        for name, (url, commit) in M.NODES[tier].items():
            d = c.custom_nodes / name
            if not d.is_dir():
                git_clone(url, d, commit)
                new_nodes.append(d)
    miss = missing_models(c, features, tier)
    print(f"② 模型 → {c.models}（缺 {len(miss)} 個，約 {sum(f[3] for f in miss):.0f} GB）")
    for repo, f, folder, _size in miss:
        print(f"   下載 {Path(f).name}", flush=True)
        fetch(repo, f, c.target(folder) / Path(f).name)
    print("✅ 下載完成")
    if new_nodes:
        print("\n接下來（只有這一次）：")
        print("  1. 用 ComfyUI Desktop 自己的 Python 安裝節點的套件：")
        for d in new_nodes:
            if (d / "requirements.txt").is_file():
                print(f"     \"{c.python()}\" -m pip install -r \"{d / 'requirements.txt'}\"")
        print("  2. 重新啟動 ComfyUI Desktop")
        print("  3. python omlocal.py check")


# ---------------------------------------------------------------- run
def run(args):
    m, base = load_manifest(args.manifest)
    m = skip_finished(m, base, args.force)
    for j in m["jobs"]:
        if j["type"] == "video":
            j.setdefault("resolution", DEFAULT_RES)
    vids = [j for j in m["jobs"] if j["type"] == "video"]
    print("這一批：" + spec_summary(m, "local"))
    if len(vids) >= 2 and not args.confirmed:
        sys.exit("兩支以上的影片：先把上面這行規格給使用者確認，確認後加 --confirmed 再跑")
    features = sorted({M.feature_of(j) for j in m["jobs"]})
    c, tier, ok = check(args, features)
    if not ok:
        sys.exit(1)

    work = base / ".omclocal"
    shutil.rmtree(work, ignore_errors=True)
    (work / "out").mkdir(parents=True)
    for j in m["jobs"]:  # the runner reads inputs/<path relative to the manifest>, like on Colab
        for f in j.get("inputs", []):
            if f and not str(f).startswith("@") and (base / f).is_file():
                (work / "inputs" / f).parent.mkdir(parents=True, exist_ok=True)
                shutil.copy(base / f, work / "inputs" / f)
    (work / "manifest.json").write_text(json.dumps(m, ensure_ascii=False, indent=1), encoding="utf-8")

    env = dict(ENV, OMC_LOCAL="1", OMC_FETCH="1", OMC_DIR=str(work), OMC_COMFY_URL=c.url,
               OMC_COMFY_INPUT=str(c.input), OMC_TIER=tier)
    runner = subprocess.Popen([sys.executable, str(SKILL / "remote" / "remote_job.py")], env=env,
                              stdout=open(work / "runner.log", "w", encoding="utf-8"), stderr=subprocess.STDOUT)
    (base / "out").mkdir(exist_ok=True)
    seen, t0, st = set(), time.time(), {}
    try:
        while True:
            time.sleep(10)
            st = json.loads((work / "status.json").read_text(encoding="utf-8")) if (work / "status.json").exists() else {}
            for jid, s in st.get("jobs", {}).items():
                if s.get("status") in ("done", "error") and jid not in seen:
                    seen.add(jid)
                    if s["status"] == "done":
                        shutil.copy(work / "out" / s["file"], base / "out" / s["file"])
                        print(f"✅ {jid} → out/{s['file']}（{s.get('seconds_used')} 秒）", flush=True)
                    else:
                        print(f"❌ {jid}：{s.get('error')}", flush=True)
            if st.get("done") or runner.poll() is not None:
                break
            running = [k for k, s in st.get("jobs", {}).items() if s.get("status") == "running"]
            print(f"…{(time.time() - t0) / 60:.1f} 分鐘　{len(seen)}/{len(m['jobs'])} 完成　正在做：{', '.join(running) or '-'}",
                  flush=True)
    finally:
        if runner.poll() is None:
            runner.terminate()
    res = dict(st.get("jobs", {}))
    (base / "out" / "results.json").write_text(json.dumps(dict(jobs=res, tier=tier, minutes=round((time.time() - t0) / 60, 1)),
                                                          ensure_ascii=False, indent=1), encoding="utf-8")
    if st.get("error") or not st.get("done"):
        print("❌ 批次失敗：" + str(st.get("error") or "runner exited")[:1500])
        print(f"   完整紀錄：{work / 'runner.log'}")
        sys.exit(1)
    done = sum(1 for v in res.values() if v.get("status") == "done")
    print(f"完成：{done}/{len(res)}，檔案在 {base / 'out'}")
    if done < len(res):
        sys.exit(2)


def main():
    ap = argparse.ArgumentParser(description="open-multimodal-colab local mode (ComfyUI Desktop)")
    ap.add_argument("--comfy", default="http://127.0.0.1:8188")
    ap.add_argument("--models-dir", help="下載到哪裡。預設 ~/ComfyUI-Shared/models（ComfyUI Desktop），沒有就用 ComfyUI 的 models")
    ap.add_argument("--comfy-dir", help="ComfyUI 的資料夾（有 input、custom_nodes 的那一層）；Desktop 會自己回報，通常不用填")
    ap.add_argument("--tier", choices=("high", "low"), help="不依 VRAM 自動判斷，直接指定等級")
    sub = ap.add_subparsers(dest="cmd", required=True)
    c = sub.add_parser("check")
    c.add_argument("--features", help="t2i,edit,video（預設全部）")
    s = sub.add_parser("setup")
    s.add_argument("--features", help="t2i,edit,video（預設全部）")
    r = sub.add_parser("run")
    r.add_argument("manifest")
    r.add_argument("--confirmed", action="store_true")
    r.add_argument("--force", action="store_true")
    args = ap.parse_args()
    if args.cmd == "check":
        sys.exit(0 if check(args, parse_features(args.features))[2] else 1)
    {"setup": setup, "run": run}[args.cmd](args)


if __name__ == "__main__":
    main()
